ALTER TABLE public.billing_plans ADD COLUMN capacity integer, ADD COLUMN badge_label text, ADD COLUMN badge_tone text NOT NULL DEFAULT 'accent', ADD COLUMN trial_enabled boolean NOT NULL DEFAULT false, ADD COLUMN trial_days integer NOT NULL DEFAULT 7;
ALTER TABLE public.asaas_contracts ADD COLUMN trial_until date;
CREATE OR REPLACE FUNCTION public.validate_plan_commercial() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.capacity IS NOT NULL AND NEW.capacity<1 THEN RAISE EXCEPTION 'Limite de vagas deve ser positivo'; END IF; IF NEW.trial_days<1 OR NEW.trial_days>30 THEN RAISE EXCEPTION 'Teste gratuito deve ter entre 1 e 30 dias'; END IF; IF length(coalesce(NEW.badge_label,''))>30 OR NEW.badge_tone NOT IN ('accent','primary','secondary') THEN RAISE EXCEPTION 'Selo inválido'; END IF; NEW.badge_label:=nullif(btrim(NEW.badge_label),''); IF NEW.trial_enabled AND (NEW.audience<>'assinante' OR NEW.plan_type<>'recorrente' OR NEW.billing_interval<>'monthly' OR NEW.contract_template_id IS NOT NULL OR NEW.amount_cents<=0) THEN RAISE EXCEPTION 'Teste gratuito exige plano mensal de Assinante sem contrato eletrônico'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_plan_commercial() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.validate_plan_commercial() TO service_role;
CREATE TRIGGER validate_plan_commercial BEFORE INSERT OR UPDATE ON public.billing_plans FOR EACH ROW EXECUTE FUNCTION public.validate_plan_commercial();
CREATE OR REPLACE FUNCTION public.enforce_plan_capacity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE limit_value integer; used bigint; BEGIN IF NEW.status NOT IN ('active','draft','past_due') THEN RETURN NEW; END IF; SELECT capacity INTO limit_value FROM public.billing_plans WHERE id=NEW.plan_id FOR UPDATE; IF limit_value IS NOT NULL THEN SELECT count(*) INTO used FROM public.billing_subscriptions WHERE plan_id=NEW.plan_id AND status IN ('active','draft','past_due') AND id<>NEW.id; IF used>=limit_value THEN RAISE EXCEPTION 'As vagas deste plano foram preenchidas'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.enforce_plan_capacity() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.enforce_plan_capacity() TO service_role;
CREATE TRIGGER enforce_plan_capacity BEFORE INSERT OR UPDATE OF plan_id,status ON public.billing_subscriptions FOR EACH ROW EXECUTE FUNCTION public.enforce_plan_capacity();
CREATE OR REPLACE FUNCTION public.get_self_service_plans() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'description',p.description,'amount_cents',p.amount_cents,'features',p.features,'badge_label',p.badge_label,'badge_tone',p.badge_tone,'trial_enabled',p.trial_enabled,'trial_days',p.trial_days,'remaining_seats',CASE WHEN p.capacity IS NULL THEN NULL ELSE greatest(0,p.capacity-(SELECT count(*) FROM public.billing_subscriptions s WHERE s.plan_id=p.id AND s.status IN ('active','draft','past_due'))) END) ORDER BY p.position,p.created_at),'[]'::jsonb) FROM public.billing_plans p WHERE p.active AND p.self_service_enabled AND p.audience='assinante' AND p.plan_type='recorrente' AND p.billing_interval='monthly' AND p.currency='BRL' AND p.amount_cents>0 AND p.contract_template_id IS NULL $$;
REVOKE ALL ON FUNCTION public.get_self_service_plans() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.get_self_service_plans() TO service_role;
DO $$ DECLARE definition text; BEGIN definition:=pg_get_functiondef('public.reserve_asaas_contract(uuid,uuid,text)'::regprocedure); definition:=replace(definition,'IF NOT FOUND THEN RAISE EXCEPTION ''Plano não disponível para contratação''; END IF;', 'IF NOT FOUND THEN RAISE EXCEPTION ''Plano não disponível para contratação''; END IF;'); definition:=replace(definition,'SELECT * INTO s FROM public.billing_subscriptions','PERFORM 1 FROM public.billing_plans WHERE id=_plan FOR UPDATE; SELECT * INTO s FROM public.billing_subscriptions'); definition:=replace(definition,'INSERT INTO public.asaas_contracts(profile_id,subscription_id,environment) VALUES(_profile,s.id,_environment)', 'INSERT INTO public.asaas_contracts(profile_id,subscription_id,environment,trial_until) VALUES(_profile,s.id,_environment,CASE WHEN p.trial_enabled AND NOT EXISTS(SELECT 1 FROM public.asaas_contracts WHERE profile_id=_profile AND trial_until IS NOT NULL) THEN (now() AT TIME ZONE ''America/Sao_Paulo'')::date+p.trial_days END)'); definition:=replace(definition,'''start_date'',s.start_date','''start_date'',coalesce(c.trial_until,s.start_date)'); EXECUTE definition; END $$;
CREATE OR REPLACE FUNCTION public.activate_asaas_trial(_contract uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.asaas_contracts%ROWTYPE; BEGIN SELECT * INTO c FROM public.asaas_contracts WHERE id=_contract; IF c.id IS NULL THEN RETURN false; END IF; PERFORM 1 FROM public.profiles WHERE id=c.profile_id AND is_active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Perfil inativo'; END IF; SELECT * INTO c FROM public.asaas_contracts WHERE id=_contract FOR UPDATE; IF c.trial_until IS NULL OR c.trial_until<=(now() AT TIME ZONE 'America/Sao_Paulo')::date OR c.remote_subscription_id IS NULL THEN RETURN false; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=c.profile_id AND role IN ('admin','facilitador','membro')) THEN RAISE EXCEPTION 'Papel interno exige gestão administrativa'; END IF; IF NOT EXISTS(SELECT 1 FROM public.billing_subscriptions WHERE id=c.subscription_id AND status IN ('draft','active')) THEN RETURN false; END IF; DELETE FROM public.user_roles WHERE user_id=c.profile_id AND role='convidado'; INSERT INTO public.user_roles(user_id,role) VALUES(c.profile_id,'assinante') ON CONFLICT DO NOTHING; UPDATE public.asaas_contracts SET paid_until=greatest(paid_until,trial_until) WHERE id=c.id; UPDATE public.billing_subscriptions SET status='active',next_charge_date=c.trial_until WHERE id=c.subscription_id; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.activate_asaas_trial(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.activate_asaas_trial(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.profile_plan_badge(_profile uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('label',p.badge_label,'tone',p.badge_tone) FROM public.billing_subscriptions s JOIN public.billing_plans p ON p.id=s.plan_id WHERE s.profile_id=_profile AND s.status='active' AND s.start_date<=(now() AT TIME ZONE 'America/Sao_Paulo')::date AND public.asaas_subscription_current(s.id) AND p.badge_label IS NOT NULL ORDER BY s.created_at DESC LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.profile_plan_badge(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.profile_plan_badge(uuid) TO service_role;
